import re


def run(question, tools):
    # 1. Portfolio requests: enforce entitlements before reading account data.
    m = re.search(r"\bA-\d+\b", question)
    if m:
        account = m.group(0)
        if not tools.is_authorized(account):
            return "UNAUTHORIZED"
        try:
            result = tools.get_portfolio(account)["total_value"]
            return str(result)
        except Exception:
            return "UNAUTHORIZED"

    # 2. Lookup questions (Company name -> Ticker -> Metric lookup).
    # Pattern: Company Name + optional year/period + metric request
    lookup_patterns = [
        r"(?i)(?:what\s+(?:is|was)\s+the)?\s*(?:current\s+)?(?:name|ticker|symbol)\s+of\s+(?P<name>[\w\s]+)",
        r"(?i)(?:what\s+(?:is|was)\s+the)?\s*revenue\s+(?:of|for|from)\s+(?P<name>[\w\s]+)",
        r"(?i)(?:what\s+(?:is|was)\s+the)?\s*(?:net\s+)?income\s+(?:of|for|from)\s+(?P<name>[\w\s]+)",
        r"(?i)(?:who\s+(?:owns|is owned by))?\s+(?P<name>[\w\s]+)",
    ]

    ticker = None
    for pattern in lookup_patterns:
        match = re.search(pattern, question)
        if match:
            name = match.group("name")
            try:
                ticker = tools.lookup_ticker(name.strip())
                break
            except Exception:
                continue

    # If we found a ticker and the question asks for revenue/income/total_value with a period
    if ticker:
        metric_pattern = r"(?i)(?:revenue|net\s+income|profit)\s*(?:in\s+(?P<period>FY\d{4}|year|20\d{2}))?"
        match = re.search(metric_pattern, question)
        period = match.group("period") if match else None

        # Try to find metric and period in the search results first for Arabic queries or specific years
        docs = tools.search(question, k=4)
        context = "\n".join("- " + d["text"] for d in docs)

        prompt = (
            f"Find the {question.lower()}. Use the provided documents.\n"
            f"Documents:\n{context}\n\n"
            f"Company: {name} ({ticker})\n"
            f"Question: What was the {(match.group(0) if match else 'FY2024')}{question.replace('What was', 'What is')}?"
        )

        try:
            llm_response = tools.llm(prompt, max_tokens=64).strip()
            # Extract number
            nums = re.findall(r"-?\d+\.?\d*", llm_response)
            if nums:
                val = float(nums[-1])
                return str(val)
        except Exception:
            pass

    # 3. Growth questions (YoY percentage change).
    growth_patterns = [
        r"(?i)(?:year\s+over\s+year|yoy)\s*percent\s+(?:change|growth)",
        r"(?i)(?:percent\s+(?:change|growth)),\s*(?:between|from)\s+(?P<year1>FY\d{4}|20\d{2})\s+and(?:\s+(?P<year2>FY\d{4}|20\d{2}))?",
    ]

    for pattern in growth_patterns:
